#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.8.1"
OLD = base64.b64decode('').decode("utf-8")
NEW = base64.b64decode('').decode("utf-8")
TEST = base64.b64decode('').decode("utf-8")
NOTE = base64.b64decode('').decode("utf-8")

ROI_REL = Path("app/services/vision_app/roi_search.py")
TEST_REL = Path("tests/vision_app/test_vision_app_v0801.py")
NOTE_REL = Path("docs/llm_context/updates/v0801_blur_template_refinement.md")

def resolve_roots(frontend_arg=None, backend_arg=None):
    cwd=Path.cwd().resolve()
    fe_candidates=[]; be_candidates=[]
    if frontend_arg: fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg: be_candidates.append(Path(backend_arg).expanduser().resolve())
    fe_candidates += [cwd, cwd/'LambdaVisionSuper', cwd.parent/'LambdaVisionSuper']
    be_candidates += [cwd, cwd/'LambdaVisionSuperBackEnd', cwd.parent/'LambdaVisionSuperBackEnd']
    frontend=next((p for p in fe_candidates if (p/'src/App.tsx').exists() and (p/'src/Pages/ComputerVisionPage.tsx').exists()), None)
    backend=next((p for p in be_candidates if (p/'app/main.py').exists() and (p/ROI_REL).exists()), None)
    if frontend is None: raise RuntimeError('Cannot locate LambdaVisionSuper frontend')
    if backend is None: raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd')
    return frontend, backend

def state(path, old, new):
    if not path.exists(): return 'MISSING'
    cur=path.read_text(encoding='utf-8')
    if cur==new: return 'OK'
    if cur==old: return 'UPDATE'
    return 'CONFLICT'

def create_state(path, desired):
    if not path.exists(): return 'CREATE'
    return 'OK' if path.read_text(encoding='utf-8')==desired else 'CONFLICT'

def scan(frontend, backend):
    print('='*96)
    print('COMPUTER VISION V0.8.1 — BLUR TEMPLATE LOCALIZATION HOTFIX')
    print('='*96)
    print(f'Frontend : {frontend}')
    print(f'Backend  : {backend}\n')
    entries=[
        ('backend/'+ROI_REL.as_posix(), state(backend/ROI_REL, OLD, NEW)),
        ('backend/'+TEST_REL.as_posix(), create_state(backend/TEST_REL, TEST)),
        ('frontend/'+NOTE_REL.as_posix(), create_state(frontend/NOTE_REL, NOTE)),
    ]
    bad=0
    for name,s in entries:
        print(f'  [{s:10}] {name}')
        bad += s in ('CONFLICT','MISSING')
    print('\nFix: blur coarse search -> grayscale local refinement; low-texture ROI uses context halo.')
    if bad: print(f'[WARN] {bad} conflict(s); apply will stop safely.')
    return 0

def preflight(frontend, backend):
    errs=[]
    s=state(backend/ROI_REL, OLD, NEW)
    if s not in ('UPDATE','OK'): errs.append(f'{ROI_REL}: {s}')
    for path,desired in ((backend/TEST_REL,TEST),(frontend/NOTE_REL,NOTE)):
        cs=create_state(path,desired)
        if cs not in ('CREATE','OK'): errs.append(f'{path}: {cs}')
    if errs: raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errs))

def regenerate_context(frontend, backend):
    gen=frontend/'tools/generate_llm_context_map.py'
    if not gen.exists():
        print('[SKIP] Context generator not found'); return
    cmd=[sys.executable,str(gen),'--frontend',str(frontend),'--backend',str(backend)]
    if '--output-dir' in gen.read_text(encoding='utf-8'):
        cmd += ['--output-dir',str(frontend/'docs/llm_context')]
    p=subprocess.run(cmd,cwd=str(frontend),text=True,capture_output=True)
    if p.returncode!=0: raise RuntimeError('Context generation failed:\n'+(p.stdout+'\n'+p.stderr).strip())
    if p.stdout.strip(): print(p.stdout.strip())

def apply(frontend, backend):
    preflight(frontend, backend)
    stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S')
    backup=frontend/'.lambda_updater_backups'/f'computer_vision_v0801_{stamp}'
    (backup/'backend/app/services/vision_app').mkdir(parents=True,exist_ok=True)
    shutil.copy2(backend/ROI_REL, backup/'backend'/ROI_REL)
    if (backend/ROI_REL).read_text(encoding='utf-8') != NEW:
        (backend/ROI_REL).write_text(NEW,encoding='utf-8'); print('[WRITE] backend/'+ROI_REL.as_posix())
    (backend/TEST_REL).parent.mkdir(parents=True,exist_ok=True)
    if not (backend/TEST_REL).exists(): (backend/TEST_REL).write_text(TEST,encoding='utf-8'); print('[WRITE] backend/'+TEST_REL.as_posix())
    (frontend/NOTE_REL).parent.mkdir(parents=True,exist_ok=True)
    if not (frontend/NOTE_REL).exists(): (frontend/NOTE_REL).write_text(NOTE,encoding='utf-8'); print('[WRITE] frontend/'+NOTE_REL.as_posix())
    print('[INFO] Regenerating LLM context docs...')
    regenerate_context(frontend,backend)
    print(f'[OK] Backup: {backup}')
    print('Run verify next.')
    return 0

def verify(frontend, backend):
    print('='*96)
    print('VERIFY COMPUTER VISION V0.8.1')
    print('='*96)
    failures=0
    exact=(backend/ROI_REL).read_text(encoding='utf-8')==NEW
    print(f'[{"OK" if exact else "FAIL"}] Coarse-to-fine blur template locator')
    failures += 0 if exact else 1
    signatures=[
        ('Low-texture context halo', 'context_pad = max(4, kernel * 2)' in NEW),
        ('Grayscale refinement', 'Refine on the original grayscale data' in NEW),
        ('v0.8.1 regression test', (backend/TEST_REL).exists()),
        ('v0.8.1 handoff note', (frontend/NOTE_REL).exists()),
    ]
    for label,ok in signatures:
        print(f'[{"OK" if ok else "FAIL"}] {label}'); failures += 0 if ok else 1
    try:
        py_compile.compile(str(backend/ROI_REL),doraise=True)
        py_compile.compile(str(backend/TEST_REL),doraise=True)
        print('[OK] Python syntax')
    except Exception as e:
        print('[FAIL] Python syntax:',e); failures += 1
    targets=[
        'tests/vision_app/test_vision_app_frame_v0100.py',
        'tests/vision_app/test_vision_app_v0800.py',
        'tests/vision_app/test_vision_app_v0801.py',
    ]
    existing=[t for t in targets if (backend/t).exists()]
    p=subprocess.run([sys.executable,'-m','pytest','-q',*existing],cwd=str(backend),text=True,capture_output=True)
    if p.returncode==0:
        print('[OK] Vision App regression tests'); print(p.stdout.strip())
    else:
        print('[FAIL] Vision App regression tests'); print((p.stdout+'\n'+p.stderr).strip()); failures += 1
    try:
        regenerate_context(frontend,backend)
        print('[OK] Regenerated LLM context docs')
    except Exception as e:
        print('[FAIL] Context regeneration:',e); failures += 1
    if failures:
        print(f'[FAIL] v0.8.1 verification finished with {failures} issue(s).'); return 1
    print('[OK] Computer Vision v0.8.1 blur-template hotfix verified.'); return 0

def main():
    p=argparse.ArgumentParser()
    p.add_argument('command',choices=['scan','apply','verify'])
    p.add_argument('--frontend'); p.add_argument('--backend')
    args=p.parse_args()
    try:
        fe,be=resolve_roots(args.frontend,args.backend)
        if args.command=='scan': return scan(fe,be)
        if args.command=='apply': return apply(fe,be)
        return verify(fe,be)
    except Exception as e:
        print('[ERROR]',e); return 2

if __name__=='__main__': raise SystemExit(main())
